spec.query:
import "date"


from(bucket: "smarthome")
|> range(start: today())
|> filter(fn: (r) => 
       (r._measurement == "zendure" and (r._field == "solarInputPower" or r._field == "outputHomePower"))
    or (r._measurement == "tasmota" and r._field == "downstream")
)
|> aggregateWindow(every: 5m, fn: mean, createEmpty: true)
|> fill(usePrevious: true)
|> group()
|> pivot(rowKey:["_time"], columnKey:["_field"], valueColumn:"_value")
|> map(fn: (r) => ({
    _time: r._time,
    _value: if r.solarInputPower > (r.outputHomePower + r.downstream)
        then r.solarInputPower - (r.outputHomePower + r.downstream)
        else 0.0,
    _field: "PV_Ueberschuss"
}))
|> aggregateWindow(
    every: 1d,
    fn: (column, tables=<-) => tables |> integral(unit: 1h),
    createEmpty: false,
)
|> map(
    fn: (r) =>
        ({
            _time: date.add(to: today(), d: 3h),
            _measurement: "daily_energy",
            _field: "pv_excess",
            _value: r._value,
        }),
)
|> to(bucket: "smarthomederived")
